/**
 * Most-recent health for each live fundamentals provider (Financial Modeling Prep, Alpha Vantage), so operators can see at a glance when a provider is rate-limited or unreachable instead of discovering it one symbol at a time.
 * @summary Live fundamentals provider status (rate limits / outages)
 */
export const GetFundamentalsProviderStatusResponse = zod.object({
  "statuses": zod.array(zod.object({
  "provider": zod.string().describe('Live provider id (financial_modeling_prep, alpha_vantage)'),
  "label": zod.string().describe('Human-readable provider name'),
  "selected": zod.boolean().describe('Whether this provider is the one selected in Settings'),
  "keyPresent": zod.boolean().describe('Whether the provider\'s API key is configured in the environment'),
  "state": zod.enum(['ok', 'rate_limited', 'unreachable', 'no_data', 'not_configured', 'idle']).describe('Derived health. ok = responding; rate_limited = temporary, recovers on its own; unreachable = misconfigured\/down; no_data = key works but no data; not_configured = no API key; idle = configured, not yet queried'),
  "message": zod.string().describe('Operator-facing explanation of the current state'),
  "lastSuccessAt": zod.string().nullish().describe('ISO timestamp of the most recent successful live fetch'),
  "lastFallbackAt": zod.string().nullish().describe('ISO timestamp of the most recent fallback to simulated data'),
  "lastFallbackReason": zod.union([zod.literal('rate_limit'),zod.literal('error'),zod.literal('no_data'),zod.literal(null)]).nullish().describe('Reason for the most recent fallback')
}))
})


